sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },
	isDatePast: function(strDate){
    // Create GlideDateTime objects for the current date and the passed in date
    var data_atual = new GlideDateTime();
    var testdate = new GlideDateTime(strDate);

    // If the testdate is before data_atual, return true, else return false
    if (testdate.before(data_atual)) {
      return true;
    }
    else {
      return false;
    }	
  },

  verificaDiaAtual: function(strDate){
	var data_atual = new GlideDateTime();
	var testDate = new GlideDateTime(strDate);
	if(testDate.isDateToday(data_atual)){
		return true;
	}else{
		return false;
	}

  },
    type: 'NeedItUtils'
};
